import numpy as np, itertools
def read(p):
    lines=open(p).read().split('\n'); n=int(lines[0])
    els=[];xyz=[]
    for l in lines[2:2+n]:
        q=l.split(); els.append(q[0]); xyz.append([float(x) for x in q[1:4]])
    return els,np.array(xyz)
els,xyz=read('opt1.xyz')
cov={'H':0.31,'C':0.76,'N':0.71,'Cl':1.02,'Pd':1.39}
bonds=[]
for i,j in itertools.combinations(range(len(els)),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if d < 1.25*(cov[els[i]]+cov[els[j]]):
        bonds.append((i,j,round(d,2)))
# print bonds per heavy atom
from collections import defaultdict
nb=defaultdict(list)
for i,j,d in bonds:
    nb[i].append((j,els[j],d)); nb[j].append((i,els[i],d))
for i in range(len(els)):
    if els[i]!='H':
        print(i,els[i],sorted(nb[i]))
